CREATE OR REPLACE FUNCTION public.guard_portal_contact_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE permitted uuid[]; BEGIN IF TG_OP='UPDATE' AND (NEW.all_sites,NEW.site_ids,NEW.email) IS DISTINCT FROM (OLD.all_sites,OLD.site_ids,OLD.email) THEN UPDATE public.client_portal_invites SET revoked_at=now() WHERE contact_id=NEW.id AND revoked_at IS NULL AND used_at IS NULL; FOR permitted IN SELECT site_ids FROM public.client_portal_memberships WHERE contact_id=NEW.id AND revoked_at IS NULL FOR UPDATE LOOP NULL; END LOOP; UPDATE public.client_portal_memberships SET all_sites=all_sites AND NEW.all_sites,site_ids=CASE WHEN all_sites THEN NEW.site_ids ELSE ARRAY(SELECT x FROM unnest(site_ids)x WHERE NEW.all_sites OR x=ANY(NEW.site_ids)) END WHERE contact_id=NEW.id AND revoked_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER client_contacts_portal_scope AFTER UPDATE ON public.client_contacts FOR EACH ROW EXECUTE FUNCTION public.guard_portal_contact_scope();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.accept_client_portal_invite(text)'::regprocedure) INTO definition; definition:=replace(definition,'INSERT INTO public.client_portal_memberships','IF EXISTS(SELECT 1 FROM public.client_portal_memberships WHERE user_id=auth.uid() AND client_id=i.client_id AND revoked_at IS NOT NULL AND revoked_at>=i.created_at) THEN RAISE EXCEPTION ''A new invitation after revocation is required''; END IF; IF NOT EXISTS(SELECT 1 FROM public.client_contacts c WHERE c.id=i.contact_id AND c.client_id=i.client_id AND c.company_id=i.company_id AND lower(trim(c.email))=i.email AND (NOT i.all_sites OR c.all_sites) AND (c.all_sites OR i.site_ids<@c.site_ids)) THEN RAISE EXCEPTION ''Contact scope changed; request a new invitation''; END IF; INSERT INTO public.client_portal_memberships'); EXECUTE definition; END $$;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.save_client_contact(uuid,uuid,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'IF NOT public.company_module_access','IF _details IS NULL OR jsonb_typeof(_details)<>''object'' OR jsonb_typeof(_details->''all_sites'') IS DISTINCT FROM ''boolean'' OR jsonb_typeof(_details->''has_whatsapp'') IS DISTINCT FROM ''boolean'' OR jsonb_typeof(_details->''site_ids'') IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''Invalid contact details or site selection''; END IF; IF NOT public.company_module_access'); EXECUTE definition; END $$;